// Project configured packages' exported store facets into literal imports.
// This is pure: gen.ts reads the manifests and owns the generated file.
import { type Config, facetsOf, used } from '@yaks/host/config'
import type { FacetName } from '@yaks/host'

export type Manifest = {
  name?: string
  exports?: string | Record<string, string>
}

// Stores serve a graph and its effects. HTTP and long-running services belong
// to their concrete hosts, so those facets never enter this import table.
let facets: FacetName[] = ['vocab', 'graph', 'effects', 'tools']

export let imports = (configs: Config[], manifests: Manifest[]): string[] => {
  let packages = new Map(manifests.map((m) => [m.name, m.exports]))
  let entries = configs.flatMap((c) => c.plugins ?? [])
  let plugins = new Set(entries.map(used))
  return [...plugins].sort().flatMap((plugin) => {
    if (!packages.has(plugin)) throw new Error(`no manifest for ${plugin}`)
    let exported = packages.get(plugin)
    return facets.filter((facet) =>
      entries.some((entry) =>
        used(entry) == plugin &&
        (facetsOf(entry) === undefined || facetsOf(entry)!.includes(facet))
      ) &&
      typeof exported == 'object' && Object.hasOwn(exported, `./${facet}`)
    ).map((facet) => `${plugin}/${facet}`)
  })
}

/** Every package's `./vocab`, configured or not: an app names any of them as a
 * `"platform"` dependency, and its store speaks their words (vocab.ts
 * `lent`). A Worker cannot import a facet it was not bundled with. */
export let vocabs = (manifests: Manifest[]): string[] =>
  manifests.filter((m) =>
    m.name?.startsWith('@yaks/') && typeof m.exports == 'object' &&
    Object.hasOwn(m.exports, './vocab')
  ).map((m) => `${m.name}/vocab`)

export let loader = (
  specifiers: string[],
  local: Record<string, string> = {},
  eager: string[] = specifiers,
): string => {
  let vocabs = specifiers.filter((s) => s.endsWith('/vocab')).sort()
  let fixed = vocabs.filter((s) => eager.includes(s))
  let lazy = vocabs.filter((s) => !eager.includes(s))
  let other = [...lazy, ...specifiers.filter((s) => !s.endsWith('/vocab'))]
  return [
    "// Generated by gen.ts from config.ts and the packages' exports. Do not edit.",
    "import type { Facets, Load, VocabFacet } from '@yaks/host'",
    ...fixed.map((s, i) =>
      `import * as vocab${i} from ${JSON.stringify(local[s] ?? s)}`
    ),
    'let vocabFacets: Record<string, VocabFacet> = {',
    ...fixed.map((s, i) => `${JSON.stringify(s.slice(0, -6))}: vocab${i},`),
    '}',
    'export let vocabFacet = (plugin: string): VocabFacet | null => {',
    'let held = vocabFacets[plugin]',
    'if (held) return held',
    'if (facets[`${plugin}/vocab`]) throw new Error(`${plugin}/vocab has not been loaded`)',
    'return null',
    '}',
    'let pending = new Map<string, Promise<unknown>>()',
    'let facets: Record<string, () => Promise<unknown>> = {',
    ...other.map((s) =>
      `${JSON.stringify(s)}: () => import(${JSON.stringify(local[s] ?? s)}),`
    ),
    '}',
    'export let load: Load = async (plugin, facet) => {',
    "if (facet == 'vocab' && vocabFacets[plugin]) return vocabFacets[plugin]",
    'let take = facets[`${plugin}/${facet}`]',
    'if (!take) return null',
    'let key = `${plugin}/${facet}`',
    'let held = pending.get(key)',
    'if (!held) {',
    'held = take().catch((e) => { pending.delete(key); throw e })',
    'pending.set(key, held)',
    '}',
    'let value = await held as Facets[typeof facet]',
    "if (facet == 'vocab') vocabFacets[plugin] = value as VocabFacet",
    'return value',
    '}',
    '',
  ].join('\n')
}
